import (
	"fmt"

	"github.com/TheManticoreProject/Manticore/network/dcerpc/syntax"
	"github.com/TheManticoreProject/Manticore/windows/guid"
)

// PipeName is retained for descriptor uniformity, but IXnRemote is NOT a named-pipe
// interface: per [MS-CMPO] 2.1 the protocol is carried over ncacn_ip_tcp on a dynamic
// endpoint that the client resolves through the RPC endpoint mapper (TCP/135) by this
// interface's UUID — the endpoint and options are passed empty to
// rpc_string_binding_compose ([MS-CMPO] 3.4.2.1). The value below is a placeholder, not
// the standard binding for this interface.
const PipeName = `\IXnRemote`

// Opnums for the on-the-wire methods.
const (
	OpnumPoke               uint16 = 0
	OpnumBuildContext       uint16 = 1
	OpnumNegotiateResources uint16 = 2
	OpnumSendReceive        uint16 = 3
	OpnumTearDownContext    uint16 = 4
	OpnumBeginTearDown      uint16 = 5
	OpnumPokeW              uint16 = 6
	OpnumBuildContextW      uint16 = 7
)

// HRESULT codes returned by the IXnRemote methods. Every method returns an HRESULT
// ([MS-DTYP] 2.2.18); success is S_OK. [MS-CMPO] does not enumerate a closed set of
// failure codes, so beyond S_OK only the standard HRESULT values a partner may surface
// are named here — any other code is rendered as hex by StatusString.
const (
	// StatusSuccess (S_OK) indicates the method succeeded.
	StatusSuccess uint32 = 0x00000000
	// StatusFail (E_FAIL) is the generic unspecified-failure HRESULT.
	StatusFail uint32 = 0x80004005
	// StatusOutOfMemory (E_OUTOFMEMORY) indicates the partner could not allocate memory.
	StatusOutOfMemory uint32 = 0x8007000E
	// StatusInvalidArg (E_INVALIDARG) indicates one or more arguments were invalid.
	StatusInvalidArg uint32 = 0x80070057
)

// SyntaxID returns the IXnRemote abstract syntax identifier:
// 906b0ce0-c70b-1067-b317-00dd010662da, version 1.0.
func SyntaxID() syntax.SyntaxID {
	return syntax.SyntaxID{
		UUID:         guid.GUID{A: 0x906b0ce0, B: 0xc70b, C: 0x1067, D: 0xb317, E: 0x00dd010662da},
		MajorVersion: 1,
		MinorVersion: 0,
	}
}

// StatusString returns a mnemonic for the recognized HRESULT codes, otherwise the hex
// value.
func StatusString(status uint32) string {
	switch status {
	case StatusSuccess:
		return "S_OK"
	case StatusFail:
		return "E_FAIL"
	case StatusOutOfMemory:
		return "E_OUTOFMEMORY"
	case StatusInvalidArg:
		return "E_INVALIDARG"
	default:
		return fmt.Sprintf("0x%08x", status)
	}
}

// OpnumToName maps each on-the-wire opnum to its method name; the single source of
// truth.
var OpnumToName = map[uint16]string{
	OpnumPoke:               "Poke",
	OpnumBuildContext:       "BuildContext",
	OpnumNegotiateResources: "NegotiateResources",
	OpnumSendReceive:        "SendReceive",
	OpnumTearDownContext:    "TearDownContext",
	OpnumBeginTearDown:      "BeginTearDown",
	OpnumPokeW:              "PokeW",
	OpnumBuildContextW:      "BuildContextW",
}

// NameToOpnum is the reverse of OpnumToName, built at init so the two never drift.
var NameToOpnum = func() map[string]uint16 {
	m := make(map[string]uint16, len(OpnumToName))
	for op, name := range OpnumToName {
		m[name] = op
	}
	return m
}()
